+double monophonic_body_magnitude_multiplier(const std::vector<NoteObject>& notes) {
+  std::vector<double> levels;
+  levels.reserve(notes.size());
+  for (const NoteObject& note : notes) {
+    const float peak = peak_rms(note);
+    if (std::isfinite(peak) && peak > 0.0f) levels.push_back(peak);
+  }
+  if (levels.empty()) return 0.0;
+
+  std::sort(levels.begin(), levels.end(), std::greater<double>());
+  const size_t set_aside = std::min(kMaxSetAsideNotes, levels.size() / kNotesPerSetAside);
+  const double reference_rms = levels[set_aside];
+  const double silence_floor = std::pow(10.0, static_cast<double>(kSilenceDb) / 20.0);
+  if (!std::isfinite(reference_rms) || reference_rms <= silence_floor) return 0.0;
+  const double multiplier = 1.0 / reference_rms;
+  return std::isfinite(multiplier) && multiplier > 0.0 ? multiplier : 0.0;
+}
