+          : reattack_sample_at_frame(*right, samples_per_frame, sample_count);
+  return boundary_sample - left_sample >= minimum_child_samples &&
+         right_sample - boundary_sample >= minimum_child_samples;
+}
+
+inline bool nearest_unused_reattack_onset(double sample_seconds,
+                                          const MonophonicOnsetEvidence& evidence,
+                                          const std::vector<bool>& used,
+                                          const std::vector<size_t>& pending,
+                                          size_t& onset_index) noexcept {
+  if (!evidence.available || !std::isfinite(sample_seconds)) return false;
+  bool found = false;
+  double best_distance = 0.0;
+  double best_onset_seconds = 0.0;
+  for (size_t i = 0; i < evidence.frames.size(); ++i) {
+    if ((i < used.size() && used[i]) ||
+        std::find(pending.begin(), pending.end(), i) != pending.end()) {
+      continue;
+    }
+    const double onset_seconds = static_cast<double>(evidence.frames[i]) / 200.0;
+    const double distance = std::abs(onset_seconds - sample_seconds);
+    if (!std::isfinite(onset_seconds) || !std::isfinite(distance) ||
+        distance > kMonophonicOnsetToleranceSeconds) {
+      continue;
+    }
+    const double tie_epsilon = 8.0 * std::numeric_limits<double>::epsilon();
+    if (!found || distance < best_distance - tie_epsilon ||
+        (std::abs(distance - best_distance) <= tie_epsilon && onset_seconds < best_onset_seconds)) {
+      found = true;
+      best_distance = distance;
+      best_onset_seconds = onset_seconds;
+      onset_index = i;
+    }
+  }
+  return found;
+}
+
+inline void commit_reattack_onsets(std::vector<bool>& used,
+                                   const std::vector<size_t>& pending) noexcept {
+  for (const size_t index : pending) {
+    if (index < used.size()) used[index] = true;
+  }
+}
+
+template <typename BuildChildren>
+inline bool build_reattack_children_with_fallback(std::vector<int>& selected_frames,
+                                                  const std::vector<int>& legacy_frames,
+                                                  bool has_augmented_cuts,
+                                                  std::vector<size_t>& pending_onsets,
+                                                  std::vector<bool>& used_onsets,
+                                                  BuildChildren&& build_children) {
+  if (build_children(selected_frames)) {
+    if (has_augmented_cuts) commit_reattack_onsets(used_onsets, pending_onsets);
+    return true;
+  }
+
+  pending_onsets.clear();
+  if (!has_augmented_cuts || legacy_frames.empty() || !build_children(legacy_frames)) return false;
+  selected_frames = legacy_frames;
+  return true;
+}

