+RateSequence multiscale_reattack_sequence(int sample_rate, int midi_note, int note_ms, float gain,
+                                          bool continuous_phase, int initial_phase_degrees) {
+  constexpr int kAttackCount = 4;
+  constexpr double kLeadSeconds = 0.2;
+  constexpr double kTailSeconds = 0.2;
+  constexpr double kAttackSeconds = 0.004;
+  constexpr double kReleaseSeconds = 0.008;
+  const double note_seconds = static_cast<double>(note_ms) / 1000.0;
+  const int64_t note_samples = static_cast<int64_t>(std::llround(note_seconds * sample_rate));
+  const int64_t lead_samples = static_cast<int64_t>(std::llround(kLeadSeconds * sample_rate));
+  const int64_t tail_samples = static_cast<int64_t>(std::llround(kTailSeconds * sample_rate));
+  RateSequence sequence;
+  sequence.notes.assign(kAttackCount, midi_note);
+  sequence.samples.assign(
+      static_cast<size_t>(lead_samples + kAttackCount * note_samples + tail_samples), 0.0f);
+  const double fundamental_hz = hz_for_midi(midi_note);
+  const double initial_phase = sonare::constants::kTwoPiD * initial_phase_degrees / 360.0;
+  double phase = initial_phase;
+  for (int attack = 0; attack < kAttackCount; ++attack) {
+    if (!continuous_phase) phase = initial_phase;
+    const int64_t start = lead_samples + static_cast<int64_t>(attack) * note_samples;
+    sequence.onsets.push_back(start);
+    for (int64_t offset = 0; offset < note_samples; ++offset) {
+      const double t = static_cast<double>(offset) / sample_rate;
+      const double envelope =
+          std::min({1.0, t / kAttackSeconds, std::max(0.0, note_seconds - t) / kReleaseSeconds});
+      phase += sonare::constants::kTwoPiD * fundamental_hz / sample_rate;
+      double value = 0.0;
+      for (int harmonic = 1; harmonic <= 5; ++harmonic) {
+        value += std::sin(harmonic * phase) / harmonic;
+      }
+      sequence.samples[static_cast<size_t>(start + offset)] =
+          static_cast<float>(gain * envelope * value);
+    }
+  }
+  return sequence;
 }

